{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.cyanheads/clinicaltrialsgov-mcp-server",
  "description": "Search ClinicalTrials.gov — find studies, retrieve results, match patients to eligible trials.",
  "repository": {
    "url": "https://github.com/cyanheads/clinicaltrialsgov-mcp-server",
    "source": "github"
  },
  "version": "2.8.2",
  "remotes": [
    {
      "type": "streamable-http",
      "url": "https://clinicaltrials.caseyjhand.com/mcp"
    }
  ],
  "packages": [
    {
      "registryType": "npm",
      "registryBaseUrl": "https://registry.npmjs.org",
      "identifier": "clinicaltrialsgov-mcp-server",
      "runtimeHint": "bun",
      "version": "2.8.2",
      "packageArguments": [
        {
          "type": "positional",
          "value": "run"
        },
        {
          "type": "positional",
          "value": "start:stdio"
        }
      ],
      "environmentVariables": [
        {
          "name": "CT_API_BASE_URL",
          "description": "ClinicalTrials.gov API base URL.",
          "format": "string",
          "isRequired": false,
          "default": "https://clinicaltrials.gov/api/v2"
        },
        {
          "name": "CT_REQUEST_TIMEOUT_MS",
          "description": "Per-request timeout in milliseconds.",
          "format": "string",
          "isRequired": false,
          "default": "30000"
        },
        {
          "name": "CT_MAX_PAGE_SIZE",
          "description": "Maximum page size cap.",
          "format": "string",
          "isRequired": false,
          "default": "200"
        },
        {
          "name": "MCP_LOG_LEVEL",
          "description": "Sets the minimum log level for output (e.g., 'debug', 'info', 'warn').",
          "format": "string",
          "isRequired": false,
          "default": "info"
        }
      ],
      "transport": {
        "type": "stdio"
      }
    },
    {
      "registryType": "npm",
      "registryBaseUrl": "https://registry.npmjs.org",
      "identifier": "clinicaltrialsgov-mcp-server",
      "runtimeHint": "bun",
      "version": "2.8.2",
      "packageArguments": [
        {
          "type": "positional",
          "value": "run"
        },
        {
          "type": "positional",
          "value": "start:http"
        }
      ],
      "environmentVariables": [
        {
          "name": "CT_API_BASE_URL",
          "description": "ClinicalTrials.gov API base URL.",
          "format": "string",
          "isRequired": false,
          "default": "https://clinicaltrials.gov/api/v2"
        },
        {
          "name": "CT_REQUEST_TIMEOUT_MS",
          "description": "Per-request timeout in milliseconds.",
          "format": "string",
          "isRequired": false,
          "default": "30000"
        },
        {
          "name": "CT_MAX_PAGE_SIZE",
          "description": "Maximum page size cap.",
          "format": "string",
          "isRequired": false,
          "default": "200"
        },
        {
          "name": "MCP_HTTP_HOST",
          "description": "The hostname for the HTTP server.",
          "format": "string",
          "isRequired": false,
          "default": "127.0.0.1"
        },
        {
          "name": "MCP_HTTP_PORT",
          "description": "The port to run the HTTP server on.",
          "format": "string",
          "isRequired": false,
          "default": "3010"
        },
        {
          "name": "MCP_HTTP_ENDPOINT_PATH",
          "description": "The endpoint path for the MCP server.",
          "format": "string",
          "isRequired": false,
          "default": "/mcp"
        },
        {
          "name": "MCP_AUTH_MODE",
          "description": "Authentication mode to use: 'none', 'jwt', or 'oauth'.",
          "format": "string",
          "isRequired": false,
          "default": "none"
        },
        {
          "name": "MCP_LOG_LEVEL",
          "description": "Sets the minimum log level for output (e.g., 'debug', 'info', 'warn').",
          "format": "string",
          "isRequired": false,
          "default": "info"
        }
      ],
      "transport": {
        "type": "streamable-http",
        "url": "http://localhost:3010/mcp"
      }
    }
  ]
}
